import{_ as e,o as d,c as o,a3 as a}from"./chunks/framework.BLaSdaBb.js";const u=JSON.parse('{"title":"开放能力","description":"","frontmatter":{},"headers":[],"relativePath":"backend/open-api.md","filePath":"backend/open-api.md","lastUpdated":1786258579000}'),r={name:"backend/open-api.md"};function c(i,t,n,p,h,s){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="开放能力" tabindex="-1">开放能力 <a class="header-anchor" href="#开放能力" aria-label="Permalink to &quot;开放能力&quot;">​</a></h1><p>BasicApp 对外开放有<strong>三条互不相同的路径</strong>，最容易混淆的是前两条方向正好相反：</p><table tabindex="0"><thead><tr><th>能力</th><th>方向</th><th>用途</th></tr></thead><tbody><tr><td><strong>OAuth2 / OIDC 服务端</strong></td><td>别人来接我</td><td>本平台作为 SSO 提供方，第三方应用「用 XiHan 账号登录」</td></tr><tr><td><strong>第三方 OAuth 登录</strong></td><td>我去接别人</td><td>登录页上的 GitHub / Gitee / Google / QQ 按钮</td></tr><tr><td><strong>开放接口（签名调用）</strong></td><td>服务端到服务端</td><td>第三方系统用 AppKey/AppSecret 签名调本平台接口，无 JWT</td></tr></tbody></table><p>第二条属于登录方式，见 <a href="./authentication#第三方登录-oauth2">身份与认证 · 第三方登录</a>。本页讲第一、三条。</p><h2 id="oauth2-oidc-服务端" tabindex="-1">OAuth2 / OIDC 服务端 <a class="header-anchor" href="#oauth2-oidc-服务端" aria-label="Permalink to &quot;OAuth2 / OIDC 服务端&quot;">​</a></h2><p>平台自己当授权服务器，让别的应用接入。</p><h3 id="应用注册-openapi-app" tabindex="-1">应用注册（<code>/openapi/app</code>） <a class="header-anchor" href="#应用注册-openapi-app" aria-label="Permalink to &quot;应用注册（`/openapi/app`）&quot;">​</a></h3><p><code>SysOAuthApp</code>：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th><th>默认</th></tr></thead><tbody><tr><td><code>AppName</code> / <code>AppDescription</code> / <code>Logo</code> / <code>Homepage</code></td><td>展示信息（同意页上给用户看）</td><td>—</td></tr><tr><td><code>ClientId</code> / <code>ClientSecret</code></td><td>客户端凭据</td><td>—</td></tr><tr><td><code>AppType</code></td><td><code>Web</code>(0) / <code>Mobile</code>(1) / <code>Desktop</code>(2)</td><td><code>Web</code></td></tr><tr><td><code>GrantTypes</code></td><td>允许的授权类型</td><td>—</td></tr><tr><td><code>RedirectUris</code></td><td>允许的回跳地址（<strong>白名单</strong>）</td><td>—</td></tr><tr><td><code>Scopes</code></td><td>可申请的授权范围</td><td>—</td></tr><tr><td><code>AccessTokenLifetime</code></td><td>访问令牌有效期（秒）</td><td><code>3600</code></td></tr><tr><td><code>RefreshTokenLifetime</code></td><td>刷新令牌有效期（秒）</td><td><code>2592000</code>（30 天）</td></tr><tr><td><code>AuthorizationCodeLifetime</code></td><td>授权码有效期（秒）</td><td><code>300</code></td></tr><tr><td><code>SkipConsent</code></td><td>跳过同意页（仅限自家可信应用）</td><td><code>false</code></td></tr></tbody></table><p>配套两张表：<code>Sys_OAuth_Code</code>（授权码）与 <code>Sys_OAuth_Token</code>（签发的令牌，支持吊销）。</p><h3 id="标准端点" tabindex="-1">标准端点 <a class="header-anchor" href="#标准端点" aria-label="Permalink to &quot;标准端点&quot;">​</a></h3><p>落在 <code>/connect/*</code>（RFC 标准路径），<strong>都是匿名端点</strong>：</p><table tabindex="0"><thead><tr><th>端点</th><th>方法</th><th>说明</th></tr></thead><tbody><tr><td><code>/connect/authorize</code></td><td>GET</td><td>浏览器入口，<strong>仅 302 跳转到已登录 SPA 的同意页</strong></td></tr><tr><td><code>/connect/token</code></td><td>POST</td><td>表单编码，用授权码/刷新令牌换令牌</td></tr><tr><td><code>/connect/revoke</code></td><td>POST</td><td>表单编码，吊销令牌（RFC 7009）</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">为什么 <code>/connect/authorize</code> 只做跳转</p><p>第一方前端用的是 <strong>JWT bearer，没有会话 Cookie</strong>，所以后端在这个匿名端点上<strong>无法判定用户是否已登录</strong>。因此它不渲染同意页，只把请求参数带着 302 到 SPA 的同意页（<code>/oauth/authorize</code>），由已登录的前端去完成确认并调后端换码。</p></div><h3 id="一个实现细节" tabindex="-1">一个实现细节 <a class="header-anchor" href="#一个实现细节" aria-label="Permalink to &quot;一个实现细节&quot;">​</a></h3><p><code>/connect/token</code> 直接注入<strong>普通 Scoped 的 <code>IOAuthServerService</code></strong>，不跨代理接口边界。这是为了避开一个已知陷阱：<strong>匿名端点没有工作单元中间件，走 Castle 代理会让拦截器急切开事务从而死锁</strong>。</p><p>同样的原因，第三方登录回调里的 <code>ExternalLoginAsync</code> 被标 <code>[DynamicApi(IsEnabled = false)]</code> 不对外暴露，且调用时用 <code>ProxyHelper.UnProxy</code> 取真实目标实例。</p><p>自己写匿名端点时记住这条，见 <a href="https://framework.docs.xihanfun.com/guide/faq#%E5%8C%BF%E5%90%8D%E7%AB%AF%E7%82%B9%E8%B0%83%E7%94%A8%E5%BA%94%E7%94%A8%E6%9C%8D%E5%8A%A1%E6%97%B6%E6%B0%B8%E4%B9%85%E6%8C%82%E8%B5%B7" target="_blank" rel="noreferrer">框架常见问题</a>。</p><h2 id="开放接口-签名调用" tabindex="-1">开放接口：签名调用 <a class="header-anchor" href="#开放接口-签名调用" aria-label="Permalink to &quot;开放接口：签名调用&quot;">​</a></h2><p>面向<strong>服务端到服务端</strong>的调用，身份由 HMAC 签名确立，<strong>不需要 JWT</strong>。</p><h3 id="凭证从哪来" tabindex="-1">凭证从哪来 <a class="header-anchor" href="#凭证从哪来" aria-label="Permalink to &quot;凭证从哪来&quot;">​</a></h3><p>用户在<a href="./authentication#个人中心">个人中心 · 开发者</a>自助申请：</p><ul><li><code>AppKey</code>（<code>ak_</code> 前缀，全局唯一）</li><li><code>AppSecret</code>（<code>sk_</code> 前缀，<strong>与账号密码同栈只存哈希，明文仅在创建/滚动时返回一次</strong>）</li></ul><p>每人最多 5 个，可随时滚动密钥或启停删除，变更均触发安全通知。实体是 <code>SysUserApiCredential</code>。</p><div class="danger custom-block"><p class="custom-block-title">AppSecret 只显示一次</p><p>创建或滚动时返回的明文<strong>不会再次提供</strong>——服务端只存哈希。当场存进你的密钥管理系统，丢了只能滚动重发。</p></div><h3 id="怎么调" tabindex="-1">怎么调 <a class="header-anchor" href="#怎么调" aria-label="Permalink to &quot;怎么调&quot;">​</a></h3><p>由框架中间件 <code>XiHanOpenApiSecurityMiddleware</code> 统一验签，只对 <code>ProtectedPathPrefixes</code> 命中的路径生效（BasicApp 配的是 <code>/api/openapi</code>）。</p><p>请求头、待签名串的构造、算法选择、两个自测端点（<code>/api/openapi/Ping</code>、<code>/api/openapi/Echo</code>）见 <a href="./../api-guide#开放接口-签名调用-无-jwt">接口对接指南 · 开放接口</a>——那里有可直接照抄的完整规则。</p><h3 id="两个必踩的坑" tabindex="-1">两个必踩的坑 <a class="header-anchor" href="#两个必踩的坑" aria-label="Permalink to &quot;两个必踩的坑&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">WARNING</p><ol><li><strong><code>ProtectedPathPrefixes</code> 别用框架默认的 <code>/api</code></strong>。框架默认值就是 <code>/api</code>，一旦开启 <code>IsEnabled</code> 而没改这项，登录、前端调用等全部接口都会要求签名。BasicApp 已在 <code>appsettings.json</code> 改成 <code>[&quot;/api/openapi&quot;]</code>。</li><li><strong>不加密请求体时必须显式发 <code>X-Encrypt-Algorithm: NONE</code></strong>，否则会走加密解析分支而失败。</li></ol></div><h3 id="调用日志" tabindex="-1">调用日志 <a class="header-anchor" href="#调用日志" aria-label="Permalink to &quot;调用日志&quot;">​</a></h3><p>开放接口的调用落 <code>Sys_OpenApi_Log</code>（按月分表），页面在 <code>/log/api</code>。排查第三方对接问题先看这里：能不能看到请求 → 验签有没有过 → 业务返回了什么。</p><h2 id="三条路径的选型" tabindex="-1">三条路径的选型 <a class="header-anchor" href="#三条路径的选型" aria-label="Permalink to &quot;三条路径的选型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>选哪条</th></tr></thead><tbody><tr><td>第三方应用想让用户「用 XiHan 账号登录」</td><td>OAuth2 服务端</td></tr><tr><td>我们的登录页想加「GitHub 登录」</td><td>第三方 OAuth 登录</td></tr><tr><td>合作方的后台系统要批量拉数据</td><td>开放接口签名调用</td></tr><tr><td>我们自己的前端调后端</td><td>都不用——直接 JWT</td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./../api-guide">接口对接指南</a>：签名算法与自测端点</li><li><a href="./authentication">身份与认证</a>：第三方登录、个人中心凭证管理</li><li><a href="./logging">审计日志</a>：开放接口日志</li><li><a href="./data-model#开放能力与审批">数据模型</a>：相关表结构</li></ul>',36)])])}const b=e(r,[["render",c]]);export{u as __pageData,b as default};
